import React, { useState, useEffect } from 'react';

const BackToTop = ({ 
  showAfter = 300,           // แสดงหลังจาก scroll ลงมาเท่าไหร่ (px)
  position = 'bottom-right', // ตำแหน่ง: 'bottom-right', 'bottom-left', 'top-right', 'top-left'
  size = 'medium',           // ขนาด: 'small', 'medium', 'large'
  color = 'blue',            // สี: 'blue', 'green', 'red', 'purple', 'gray'
  showText = false,          // แสดงข้อความหรือไม่
  smoothScroll = true        // ใช้ smooth scroll หรือไม่
}) => {
  const [isVisible, setIsVisible] = useState(false);

  // ตรวจสอบการ scroll และแสดง/ซ่อนปุ่ม
  useEffect(() => {
    const toggleVisibility = () => {
      if (window.pageYOffset > showAfter) {
        setIsVisible(true);
      } else {
        setIsVisible(false);
      }
    };

    window.addEventListener('scroll', toggleVisibility);
    return () => window.removeEventListener('scroll', toggleVisibility);
  }, [showAfter]);

  // ฟังก์ชัน scroll ขึ้นด้านบน
  const scrollToTop = () => {
    if (smoothScroll) {
      window.scrollTo({
        top: 0,
        behavior: 'smooth'
      });
    } else {
      window.scrollTo(0, 0);
    }
  };

  // กำหนดขนาดปุ่ม
  const getSizeClasses = () => {
    switch (size) {
      case 'small':
        return 'p-2';
      case 'large':
        return 'p-4';
      default:
        return 'p-3';
    }
  };

  // กำหนดขนาดไอคอน
  const getIconSize = () => {
    switch (size) {
      case 'small':
        return 'w-5 h-5';
      case 'large':
        return 'w-8 h-8';
      default:
        return 'w-6 h-6';
    }
  };

  // กำหนดสี
  const getColorClasses = () => {
    switch (color) {
      case 'green':
        return 'bg-green-600 hover:bg-green-700 focus:ring-green-500';
      case 'red':
        return 'bg-red-600 hover:bg-red-700 focus:ring-red-500';
      case 'purple':
        return 'bg-purple-600 hover:bg-purple-700 focus:ring-purple-500';
      case 'gray':
        return 'bg-gray-600 hover:bg-gray-700 focus:ring-gray-500';
      default:
        return 'bg-blue-600 hover:bg-blue-700 focus:ring-blue-500';
    }
  };

  // กำหนดตำแหน่ง
  const getPositionClasses = () => {
    switch (position) {
      case 'bottom-left':
        return 'bottom-6 left-6';
      case 'top-right':
        return 'top-6 right-6';
      case 'top-left':
        return 'top-6 left-6';
      default:
        return 'bottom-6 right-6';
    }
  };

  // ข้อความภาษาไทย
  const getText = () => {
    if (!showText) return null;
    
    return (
      <span className="ml-2 font-medium">
        {size === 'small' ? 'ขึ้น' : 'ขึ้นด้านบน'}
      </span>
    );
  };

  return (
    <>
      {isVisible && (
        <button
          onClick={scrollToTop}
          className={`
            fixed ${getPositionClasses()} z-50 
            ${getColorClasses()} 
            text-white rounded-full ${getSizeClasses()} 
            shadow-lg transition-all duration-300 
            transform hover:scale-110 focus:outline-none 
            focus:ring-2 focus:ring-offset-2
            ${showText ? 'flex items-center' : ''}
          `}
          aria-label="กลับขึ้นด้านบน"
          title="กลับขึ้นด้านบน"
        >
          <svg
            className={getIconSize()}
            fill="none"
            stroke="currentColor"
            viewBox="0 0 24 24"
            xmlns="http://www.w3.org/2000/svg"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2}
              d="M5 10l7-7m0 0l7 7m-7-7v18"
            />
          </svg>
          {getText()}
        </button>
      )}
    </>
  );
};

export default BackToTop;
